function decodeEntities(value) {
  const named = { amp: '&', apos: "'", gt: '>', lt: '<', nbsp: ' ', quot: '"' };
  return value.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (entity, reference) => {
    const lower = reference.toLowerCase();
    if (lower[0] !== '#') return named[lower] ?? entity;
    const codePoint = lower.startsWith('#x')
      ? Number.parseInt(lower.slice(2), 16)
      : Number.parseInt(lower.slice(1), 10);
    try { return String.fromCodePoint(codePoint); } catch { return entity; }
  });
}

function htmlToText(value) {
  return decodeEntities(value)
    .replace(/<br\s*\/?\s*>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function htmlToMarkdown(value) {
  const withLinks = value.replace(/<a\b([^>]*)>([\s\S]*?)<\/a>/gi, (anchor, attributes, label) => {
    const href = attributes.match(/\bhref\s*=\s*(["'])(.*?)\1/i)?.[2];
    const text = htmlToText(label);
    return href && text ? `[${text}](${decodeEntities(href)})` : text;
  });
  return htmlToText(withLinks);
}

function elementValue(entry, name) {
  const openingTag = `<${name}`.toLowerCase();
  const lowerEntry = entry.toLowerCase();
  const start = lowerEntry.indexOf(openingTag);
  if (start < 0) return '';

  const tagEnd = entry.indexOf('>', start);
  const end = lowerEntry.indexOf(`</${name}>`, tagEnd + 1);
  return tagEnd < 0 || end < 0 ? '' : htmlToText(entry.slice(tagEnd + 1, end));
}

function changesFrom(content) {
  const paragraph = /<p(?:\s[^>]*)?>\s*(Changes since[\s\S]*?)<\/p>/i.exec(content);
  if (!paragraph || paragraph.index === undefined) {
    return { changesSince: 'Changes since the previous release:', changes: [] };
  }

  const changesSince = htmlToText(paragraph[1]);
  const afterParagraph = content.slice(paragraph.index + paragraph[0].length);
  const list = /^\s*<ul\b[^>]*>([\s\S]*?)<\/ul>/i.exec(afterParagraph);
  const changes = list
    ? [...list[1].matchAll(/<li\b[^>]*>([\s\S]*?)<\/li>/gi)]
      .map((match) => htmlToMarkdown(match[1]))
      .filter(Boolean)
    : [];

  return { changesSince, changes };
}

function escapeMarkdown(value) {
  return value.replace(/([\\`*_{}[\]<>])/g, '\\$1');
}

const feedXml = String($input.first().json.feed_xml ?? '');
const entries = [...feedXml.matchAll(/<entry\b[^>]*>([\s\S]*?)<\/entry>/gi)];

return entries.flatMap((match) => {
  const entry = match[1];
  const releaseId = elementValue(entry, 'id');
  const title = elementValue(entry, 'title');
  const publishedAt = elementValue(entry, 'published') || elementValue(entry, 'updated');
  const releaseUrl = decodeEntities(entry.match(/<link\b[^>]*\bhref\s*=\s*(["'])(.*?)\1/i)?.[2] ?? '');
  const content = entry.match(/<content\b[^>]*>([\s\S]*?)<\/content>/i)?.[1] ?? '';

  if (!releaseId || !title || !releaseUrl || !content) return [];

  const { changesSince, changes } = changesFrom(content);
  const changeLines = changes.length
    ? changes.map((change) => `- ${change}`)
    : ['- No itemised changes were published for this release.'];

  return [{
    json: {
      release_id: releaseId,
      title,
      release_url: releaseUrl,
      changes_since: changesSince,
      published_at: publishedAt || null,
      first_seen_at: new Date().toISOString(),
      message: [
        `🔒 **GrapheneOS release: ${escapeMarkdown(title)}**`,
        '',
        changesSince,
        ...changeLines,
        '',
        `[View the full release notes](${releaseUrl})`,
      ].join('\n'),
      matrix_request_id: `grapheneos-release-${encodeURIComponent(releaseId)}`,
    },
  }];
});

const release = $('Prepare GrapheneOS release alerts').item.json;

return {
  json: {
    release_id: release.release_id,
    title: release.title,
    release_url: release.release_url,
    changes_since: release.changes_since,
    published_at: release.published_at,
    first_seen_at: release.first_seen_at,
    matrix_event_id: $json.event_id ?? null,
  },
};
